    post_test_digest = build_impact_digest(ROOT, changed_files, tests)
    if post_test_digest != digest:
        CACHE_PATH.unlink(missing_ok=True)
        print("failed: content/config/runtime mutated during tests; success discarded.")
        raise SystemExit(1)
    if cache_enabled:
