node .task/dependable-portions-slice1/dv-provider/acceptance.cjs --cleanup --public-closed --api-container whats-for-supper-api --base-url http://localhost:3388 --candidate <full-sha>
```

Cleanup rereads fixture identity and assignment/removal token, removes only its own assigned occurrence, restores prior day override with the current version guard, and soft-deletes its new recipe IDs (no purge). Retained fixture workflow/history/category records and an initialized empty future plan may remain; they are not silently deleted. If any capture result is unknown, reconcile that source/marker against authoritative state before retry or teardown. Do not report original totalDB rowcount restored merely because active recipe count is restored.
// Task-owned DV acceptance. No product/test-control endpoints, DB writes, resets,
// bindings, or library conversions. Execution requires explicit --run/--cleanup.
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const {execFileSync}=require('node:child_process');
const {chromium,expect}=require('../../../pwa/node_modules/@playwright/test');
const args=process.argv.slice(2);
function value(name,fallback){const i=args.indexOf(name);return i<0?fallback:args[i+1];}
const base=value('--base-url','http://localhost:3388');
const apiContainer=value('--api-container');
const marker='dvportion-7f2a1c9e4b63';
const source=value('--source-url',`http://host.docker.internal:3491/fixtures/${marker}/recipe.html`);
const candidate=value('--candidate');
const reportPath=value('--report',path.join(__dirname,'acceptance-result.json'));
const cleanup=args.includes('--cleanup');
const run=args.includes('--run');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function invariant(ok,message){if(!ok)throw Error(message);}
let report,headers;
function save(){fs.writeFileSync(reportPath,JSON.stringify(report,null,2)+'\n',{mode:0o600});}
async function call(method,route,data){
 const request={method,headers:{...headers},signal:AbortSignal.timeout(30000)};
 if(data instanceof FormData)request.body=data;
 else if(data!==undefined){request.headers['Content-Type']='application/json';request.body=JSON.stringify(data);}
 const response=await fetch(base+route,request);
 const text=await response.text();let body;try{body=text?JSON.parse(text):null;}catch{body=null;}
 invariant(response.ok,`${method} ${route.split('?')[0]} failed HTTP ${response.status}`);
 return body;
}
const unwrap=b=>b&&Object.hasOwn(b,'data')?b.data:b;
const recipe=async id=>(await call('GET',`/api/recipes/${id}`)).recipe;
const week=async(ref,offset=0)=>unwrap(await call('GET',`/api/schedule?weekOffset=${offset}&referenceWeekStartDate=${ref}`));
