 const form=new FormData();form.append('files',new Blob([fs.readFileSync(path.join(__dirname,'photo.png'))],{type:'image/png'}),marker+'.png');
 form.append('finishedDishImageIndex','-1');form.append('notes','DV external fixture '+marker);
 report.photoIntent={kind:'photo',photoSha256:crypto.createHash('sha256').update(fs.readFileSync(path.join(__dirname,'photo.png'))).digest('hex'),at:new Date().toISOString(),outcome:'pending'};save();
 const photographed=unwrap(await call('POST','/api/recipes',form));
