  await cook.evaluate(()=>window.dispatchEvent(new Event('focus')));await expect(cook.getByTestId('cooking-quantities-available')).toBeVisible();
  await expect(cook.getByTestId('cooks-mode-instructions')).toContainText(`Add all 400 g ${marker} pasta.`);
  await cook.getByRole('button',{name:'Refresh quantities',exact:true}).click();await expect(cook.getByTestId('cooks-mode-instructions')).toContainText(`Add all 500 g ${marker} pasta.`);
