  report.steps.cook={passed:true,retainedSauceCheck:true,contentRevision:stepSaved.contentRevision};save();
  const demand=await until('one exact grocery demand',async()=>{const w=await week(ref);const rows=(w.groceryItems||[]).filter(r=>r.normalizedKey===marker+' pasta');return rows.length===1&&rows[0].quantity?.value?.n==='500'&&rows[0].quantity?.value?.d==='1'?w:null;});
