function ToastItem({ toast, onDismiss }: { toast: any; onDismiss: (id: string) => void }) {
  useEffect(() => {
    if (toast.persistent) return;

    const timer = setTimeout(() => {
      onDismiss(toast.id);
    }, TOAST_DURATION);

    return () => clearTimeout(timer);
  }, [toast.id, toast.persistent, onDismiss]);

