export async function pinCivilDate(page: Page, isoDate: string) {
  await page.addInitScript((value) => {
    const RealDate = Date;
    const pinned = new RealDate(value).getTime();
    // @ts-ignore
    globalThis.Date = class extends RealDate {
      constructor(...args: any[]) {
        if (args.length === 0) {
          super(pinned);
        } else {
          // @ts-ignore
          super(...args);
        }
      }
      static now() {
        return pinned;
      }
    };
  }, isoDate);
}
