                    workflowInstanceId,
                    sourceWorkflowId = instance.WorkflowId,
                    reason = "user-cleared-failed-capture",
                }, JsonDefaults.CamelCase),
                RequestedBy = requestedBy,
                CreatedAt = clock.UtcNow,
